class GraphRestrictionRepositoryTest {

	private static final String NAMESPACE = "urn:gbj:";
	private static final String QUERY = """
			PREFIX : <urn:gbj:>
			SELECT ?g ?s ?o {
				VALUES (?g ?s) { (:graph :wanted) (:graph :wanted) (:graph :missing) }
				GRAPH ?g { ?s :p ?o . ?s :flag :yes }
			}
			""";
	private static final String SNAPSHOT_QUERY = """
			PREFIX : <urn:gbj:>
			SELECT ?s ?o { VALUES ?s { :a :b :a } GRAPH :graph { ?s :p ?o } }
			""";

	@TempDir
	Path dataDirectory;

	@Test
	void restrictedRepetitionRetainsOptionalPathEndpoint() {
		assertRestrictedPathResult(":a :p :b", "VALUES ?o { :b } GRAPH :g { :a (:p?)+ ?o }", "b");
	}

	@Test
	void restrictedOptionalPathEmitsOneIdentityForAbsentTerm() {
		assertRestrictedPathResult(":a :p :b", "VALUES ?o { :z } GRAPH :g { :z (:p*/:q*)? ?o }", "z");
	}

	@Test
	void restrictedRepetitionTraversesMultipleHopsInEitherDirection() {
		String chain = ":a :p :b . :b :p :c";
		assertRestrictedPathResult(chain, "VALUES ?o { :c } GRAPH :g { :a (:p?)+ ?o }", "c");
		assertRestrictedPathResult(chain, "VALUES ?o { :a } GRAPH :g { ?o (:p?)+ :c }", "a");
		assertRestrictedPathResult(chain, "VALUES ?o { :c } GRAPH :g { ?o (^:p?)* :a }", "c");
	}

	@Test
	void restrictedOptionalPathPreservesAlternativesAndRepeatedInputs() {
		assertRestrictedPathResult(":a :p :b", "VALUES ?o { :z } GRAPH :g { :z ((:p*/:q*)? | (:p*/:q*)?) ?o }",
				"z", "z");
		assertRestrictedPathResult(":a :p :b", "VALUES ?o { :z :z } GRAPH :g { :z (:p*/:q*)? ?o }", "z", "z");
	}

	private static void assertRestrictedPathResult(String triples, String pattern, String... expectedObjects) {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			ValueFactory values = connection.getValueFactory();
			connection.prepareUpdate("PREFIX : <urn:gbj:> INSERT DATA { GRAPH :g { " + triples + " } }").execute();
			connection.begin(IsolationLevels.SNAPSHOT_READ);
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(
					"PREFIX : <urn:gbj:> SELECT ?o WHERE { " + pattern + " }");
			List<BindingSet> expected = Stream.of(expectedObjects)
					.<BindingSet>map(name -> new ListBindingSet(List.of("o"), values.createIRI(NAMESPACE, name)))
					.toList();
			assertThat(QueryResults.asList(query.evaluate())).as(pattern).containsExactlyInAnyOrderElementsOf(expected);
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(plans(plan)).as("executed a path probe for %s", pattern)
					.anyMatch(node -> node.getLongMetricActual("graphRestrictionPathProbes") != null
							&& node.getLongMetricActual("graphRestrictionPathProbes") > 0);
			connection.commit();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void defaultLmdbUsesGraphRestrictionWithTheStandardEvaluator() {
		LmdbStore sail = new LmdbStore(dataDirectory.resolve("lmdb-default").toFile());
		assertThat(sail.isExperimentalQueryOptimizations()).isFalse();
		assertThat(sail.isNativeQueryEngineEnabled()).isFalse();
		SailRepository repository = new SailRepository(sail);
		try (var connection = repository.getConnection()) {
			seed(connection);
			connection.begin(IsolationLevels.SNAPSHOT_READ);
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
			ValueFactory values = connection.getValueFactory();
			MapBindingSet expected = statementRow(values.createIRI(NAMESPACE, "wanted"),
					values.createIRI(NAMESPACE, "match"));
			expected.addBinding("g", values.createIRI(NAMESPACE, "graph"));
			assertThat(QueryResults.asList(query.evaluate())).containsExactly(expected, expected);
			assertThat(usesRestrictionPlan(query)).as("default GRAPH restriction plan").isTrue();
			connection.commit();
		} finally {
			repository.shutDown();
		}
	}

	@TestFactory
	Stream<DynamicTest> independentAndRestrictedPlansAgreeThroughRepositoryApi() {
		return Stream.of(Backend.values())
				.flatMap(backend -> Stream.of(GraphRestrictionMode.values())
						.map(mode -> DynamicTest.dynamicTest(backend + " " + mode, () -> verifyMode(backend, mode))));
	}

	@TestFactory
	Stream<DynamicTest> openRestrictedResultRetainsItsSnapshotAcrossACommit() {
		return Stream.of(Backend.values())
				.map(backend -> DynamicTest.dynamicTest(backend.toString(),
						() -> assertTimeoutPreemptively(Duration.ofSeconds(30), () -> verifySnapshot(backend))));
	}

	private void verifySnapshot(Backend backend) {
		AbstractSail sail = backend.newSail(dataDirectory.resolve(backend + "-snapshot"));
		sail.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT
				.withGraphRestrictionMode(GraphRestrictionMode.REQUIRE_RESTRICTED));
		SailRepository repository = new SailRepository(sail);
		try (var reader = repository.getConnection(); var writer = repository.getConnection()) {
			ValueFactory values = reader.getValueFactory();
			IRI a = values.createIRI(NAMESPACE, "a");
			IRI b = values.createIRI(NAMESPACE, "b");
			IRI graph = values.createIRI(NAMESPACE, "graph");
			IRI predicate = values.createIRI(NAMESPACE, "p");
			IRI first = values.createIRI(NAMESPACE, "first");
			IRI second = values.createIRI(NAMESPACE, "second");
			IRI replacementA = values.createIRI(NAMESPACE, "replacement-a");
			IRI replacementB = values.createIRI(NAMESPACE, "replacement-b");
			writer.begin();
			writer.add(a, predicate, first, graph);
			writer.add(b, predicate, second, graph);
			writer.commit();

			SailTupleQuery query = (SailTupleQuery) reader.prepareTupleQuery(SNAPSHOT_QUERY);
			reader.begin(IsolationLevels.SNAPSHOT_READ);
			assertThat(usesRestrictionPlan(query)).isTrue();
			List<BindingSet> sameSnapshot = new ArrayList<>();
			try (var rows = query.evaluate()) {
				assertThat(rows.hasNext()).isTrue();
				sameSnapshot.add(rows.next());

				// The result remains open with two driving occurrences still to be delivered.
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				writer.remove(a, predicate, first, graph);
				writer.remove(b, predicate, second, graph);
				writer.add(a, predicate, replacementA, graph);
				writer.add(b, predicate, replacementB, graph);
				writer.commit();

				rows.forEachRemaining(sameSnapshot::add);
			}
			assertThat(sameSnapshot).containsExactlyInAnyOrder(
					statementRow(a, first), statementRow(b, second), statementRow(a, first));
			reader.commit();

			reader.begin(IsolationLevels.SNAPSHOT_READ);
			assertThat(QueryResults.asList(query.evaluate())).containsExactlyInAnyOrder(
					statementRow(a, replacementA), statementRow(b, replacementB), statementRow(a, replacementA));
			reader.commit();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(30)
	void nativeDirectWriterMakesAutoUseIndependentReadUntilTheWriterCloses() {
		AbstractSail sail = Backend.NATIVE.newSail(dataDirectory.resolve("direct-writer"));
		sail.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT.withGraphRestrictionMode(GraphRestrictionMode.AUTO));
		SailRepository repository = new SailRepository(sail);
		try (var reader = repository.getConnection(); var writer = repository.getConnection()) {
			seed(writer);
			ValueFactory values = reader.getValueFactory();
			IRI graph = values.createIRI(NAMESPACE, "graph");
			IRI wanted = values.createIRI(NAMESPACE, "wanted");
			IRI match = values.createIRI(NAMESPACE, "match");
			SailTupleQuery query = (SailTupleQuery) reader.prepareTupleQuery(QUERY);
			MapBindingSet expected = statementRow(wanted, match);
			expected.addBinding("g", graph);

			writer.begin(IsolationLevels.NONE);
			writer.add(wanted, values.createIRI(NAMESPACE, "p"), match, values.createIRI(NAMESPACE, "other"));
			assertThat(usesRestrictionPlan(query)).isFalse();
			try (var firstRow = query.evaluate()) {
				assertThat(firstRow.hasNext()).isTrue();
				assertThat(firstRow.next()).isEqualTo(expected);
			}
			assertThat(writer.isActive()).isTrue();
			writer.rollback();

			reader.begin(IsolationLevels.SNAPSHOT_READ);
			assertThat(usesRestrictionPlan(query)).isTrue();
			assertThat(QueryResults.asList(query.evaluate())).containsExactly(expected, expected);
			reader.commit();
		} finally {
			repository.shutDown();
		}
	}

	private void verifyMode(Backend backend, GraphRestrictionMode mode) {
		Path path = dataDirectory.resolve(backend.name() + "-" + mode);
		if (backend == Backend.NATIVE) {
			SailRepository seedRepository = new SailRepository(backend.newSail(path));
			try (var connection = seedRepository.getConnection()) {
				seed(connection);
			} finally {
				seedRepository.shutDown();
			}
		}
		AbstractSail sail = backend.newSail(path);
		sail.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT.withGraphRestrictionMode(mode));
		SailRepository repository = new SailRepository(sail);
		try (var connection = repository.getConnection()) {
			if (backend == Backend.MEMORY) {
				seed(connection);
			}
			connection.begin(IsolationLevels.SNAPSHOT_READ);
			verifyPreparedQuery(connection, mode);
			connection.commit();
		} finally {
			repository.shutDown();
		}
	}

	private static void verifyPreparedQuery(RepositoryConnection connection, GraphRestrictionMode mode) {
		ValueFactory values = connection.getValueFactory();
		IRI graph = values.createIRI(NAMESPACE, "graph");
		IRI wanted = values.createIRI(NAMESPACE, "wanted");
		IRI expectedObject = values.createIRI(NAMESPACE, "match");
		MapBindingSet row = statementRow(wanted, expectedObject);
		row.addBinding("g", graph);
		List<BindingSet> expected = List.of(row, row);

		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
		assertThat(TupleExprs.containsGraphBoundary(query.getParsedQuery().getTupleExpr())).isTrue();
		SimpleDataset dataset = new SimpleDataset();
		dataset.addNamedGraph(graph);
		query.setDataset(dataset);
		assertThat(QueryResults.asList(query.evaluate())).as("result bag in mode %s", mode)
				.containsExactlyInAnyOrderElementsOf(expected);
		boolean restricted = usesRestrictionPlan(query);
		if (mode == GraphRestrictionMode.REQUIRE_RESTRICTED) {
			assertThat(restricted).as("restricted join in mode %s", mode).isTrue();
		} else if (mode == GraphRestrictionMode.FORCE_INDEPENDENT || mode == GraphRestrictionMode.OFF) {
			assertThat(restricted).as("restricted join in mode %s", mode).isFalse();
		} else {
			SailTupleQuery unbound = (SailTupleQuery) connection.prepareTupleQuery("""
					PREFIX : <urn:gbj:>
					SELECT ?s ?o {
						VALUES (?s ?payload) { (UNDEF 1) (UNDEF 2) }
						GRAPH :graph { ?s :p ?o }
					}
					""");
			assertThat(usesRestrictionPlan(unbound)).as("AUTO join with no bound seek keys").isFalse();
		}
	}

	private static MapBindingSet statementRow(IRI subject, IRI object) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("s", subject);
		row.addBinding("o", object);
		return row;
	}

	private static boolean usesRestrictionPlan(SailTupleQuery query) {
		GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
		return plans(plan).anyMatch(node -> "RestrictionBindJoinIteration".equals(node.getAlgorithm()));
	}

	private static Stream<GenericPlanNode> plans(GenericPlanNode node) {
		List<GenericPlanNode> children = node.getPlans();
		return Stream.concat(Stream.of(node), children == null ? Stream.empty()
				: children.stream()
						.flatMap(
								GraphRestrictionRepositoryTest::plans));
	}

	private static void seed(RepositoryConnection connection) {
		ValueFactory values = connection.getValueFactory();
		IRI graph = values.createIRI(NAMESPACE, "graph");
		IRI decoy = values.createIRI(NAMESPACE, "decoy");
		IRI p = values.createIRI(NAMESPACE, "p");
		IRI flag = values.createIRI(NAMESPACE, "flag");
		IRI yes = values.createIRI(NAMESPACE, "yes");
		IRI wanted = values.createIRI(NAMESPACE, "wanted");
		connection.begin();
		for (int i = 0; i < 128; i++) {
			IRI subject = values.createIRI(NAMESPACE, "s" + i);
			connection.add(subject, p, values.createIRI(NAMESPACE, "o" + i), graph);
			connection.add(subject, flag, yes, graph);
		}
		connection.add(wanted, p, values.createIRI(NAMESPACE, "match"), graph);
		connection.add(wanted, flag, yes, graph);
		connection.add(wanted, p, values.createIRI(NAMESPACE, "outside"), decoy);
		connection.add(wanted, flag, yes, decoy);
		connection.commit();
	}

	private enum Backend {
		MEMORY,
		NATIVE;

		AbstractSail newSail(Path dataDirectory) {
			return switch (this) {
			case MEMORY -> new MemoryStore();
			case NATIVE -> new NativeStore(dataDirectory.toFile(), "spoc,posc,ospc");
			};
		}
	}
}
